from pathlib import Path
p=Path('reproduction/COMMANDS.md');s=p.read_text(encoding='utf-8-sig').replace('僅新增 `--config` 路徑經過本輪驗證；legacy CLI 不需要使用，也不宣稱已全面相容其他蒸餾方法。','目前兩個訓練入口只接受新的 `--config` 路徑；`--help` 可直接使用。legacy CLI 已明確停用，原碼仍保留於 reference，不宣稱支援其他蒸餾方法。')
s=s.replace('& ./.venv/Scripts/python.exe reproduction/test_semantics.py\n& ./.venv/Scripts/python.exe reproduction/test_results.py\n& ./reproduction/prepare.ps1','& ./.venv/Scripts/python.exe reproduction/test_no_data.py\n# 以下需要下一階段授權；本輪不執行：\n# & ./.venv/Scripts/python.exe reproduction/test_semantics.py Semantics.test_sampler_real\n# & ./reproduction/prepare.ps1')
s+='\n## 2026-09-17 程式查核補充\n\n`test_no_data.py` 不讀 CIFAR100；會使用已核對的教師 checkpoint 與合成影像，執行必要 forward/backward、模擬執行入口與完整 resume。合成測試結果存在 artifacts/preflight，不是正式研究 run。\n\nresume checkpoint schema 現為2，加入完整 epoch metrics 歷史。checkpoint 是唯一提交點，metrics/status/推論檔可從它重建。若最後 epoch 已完成但結果發布中斷，再執行 resume 只修復結果檔，不追加訓練。舊 schema1 測試 checkpoint 不相容；尚無正式訓練 checkpoint 需要遷移。\n\n限定 workers=0、預定正式 seeds0–4；未知設定欄位與不同 runtime environment 都拒絕接續。每步新增非有限 loss/gradient/parameter 檢查，不裁剪梯度、不改 loss。失敗時從上一個完整 epoch 的 checkpoint 接續；forward 已更新的 memory 不會單步回滾。記錄中的 seconds/elapsed_seconds 是 train+evaluation 時間，不含 checkpoint I/O 與初始教師評估。\n'
p.write_text(s,encoding='utf8')
p=Path('reproduction/SOURCE_AUDIT.md');s=p.read_text(encoding='utf-8-sig');s+='\n## 2026-09-17 額外工程查核（本次新增規約）\n\n完整 checkpoint schema2 保存 epoch history；寫入使用同目錄暫存檔、flush/fsync 與 replace。以最後完整 checkpoint 重建 metrics/status/student_final，可恢復發布中斷。run 使用 OS 檔案鎖避免同時寫入；resume 先檢查 config、code hash、commit、teacher checksum、environment，再修改結果。正式結果另外檢查240 epochs、187680 steps、完整split大小、teacher來源、code/config/environment一致性。未知 config 與未預定 seeds 不接受。\n\n訓練入口現統一接受 --config；舊 tensorboard_logger 分支不再作為執行路徑。可用 --help 查看完整 CLI。加入 loss、gradient、更新後參數及評估輸出的 NaN/Inf 檢查，只偵測異常，不改有效數值或引入 gradient clipping。CRD 的 loss、Z 與 memory 公式維持原作者數值流程。\n'
p.write_text(s,encoding='utf8')
p=Path('reproduction/REPRODUCTION_README.md');s=p.read_text(encoding='utf-8-sig').replace('`REPORT.md`：本輪實際驗證結果與資源估計（完成測試後填入）。','`PREFLIGHT_REPORT.md`：不依賴 CIFAR100 的程式查核結果；真實資料驗證尚未啟動。').replace('`test_semantics.py`、`test_results.py`','`test_no_data.py`、`test_semantics.py`、`test_preflight.py`、`test_results.py`');p.write_text(s,encoding='utf8')
